UPDATE `locales_quest` SET `title_loc8`='Жажда Джерарда',`offerrewardtext_loc8`='Благодарю, $N! Решишь еще со мной поторговаться – заходи.' WHERE `entry`=16;
UPDATE `locales_quest` SET `RequestItemsText_loc8`='Работа фермера тяжела, от нее здорово пересыхает в глотке.$B$BЕсли ты дашь мне родниковой воды, могу предложить кое-что взамен.' WHERE `entry`=16;
