UPDATE `locales_quest` SET `title_loc8`='Печальная история',`details_loc8`='Прежде чем мы продолжим, тебе следует услышать мою историю.',`objectives_loc8`='Послушайте, как павший герой Орды рассказывает свою историю.',`offerrewardtext_loc8`='Настало время действовать, $N.' WHERE `entry`=2801;
