UPDATE `locales_quest` SET `title_loc8`='Дымящиеся руины Тауриссана',`details_loc8`='Не желаете ли услышать краткий обзор истории дворфов Черного Железа?',`objectives_loc8`='Узнайте от королевского историка Аркессона историю Тауриссана.',`offerrewardtext_loc8`='Продолжим?' WHERE `entry`=3702;
