UPDATE `locales_quest` SET `title_loc8`='Лекарство из оскверненных трав',`offerrewardtext_loc8`='Отличная работа, $N – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!' WHERE `entry`=4105;
