UPDATE `locales_quest` SET `title_loc8`='Оскверненный песнецвет',`offerrewardtext_loc8`='Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.' WHERE `entry`=4401;
