UPDATE `locales_quest` SET `title_loc8`='Манускрипт ненасытности',`offerrewardtext_loc8`='Голова болит... Сила бескрайних пределов вселенной... Ахххх!$B$B*Матредис кривится от боли.*$B$BБери, что тебе нужно, и уходи!' WHERE `entry`=4484;
