UPDATE `locales_quest` SET `title_loc8`='Ловкость Агамаггана',`offerrewardtext_loc8`='Да будет верной твоя цель и метким оружие, |3-6($R).$B$BДух Агамаггана пребывает с тобой. *фыркает* Возвращайся, если захочешь. Кривозуб снова благословит тебя, если будет на то воля великого кабаньего бога. *фыркает*' WHERE `entry`=5043;
