UPDATE `locales_quest` SET `title_loc8`='Мудрость Агамаггана',`offerrewardtext_loc8`='Теперь враги будут трепетать от одного твоего вида, |3-6($R). *фыркает*$B$BПоведай Кривозубу о своих битвах, когда мы встретимся в следующий раз – в этой жизни или в следующей. *фыркает*' WHERE `entry`=5044;
