UPDATE `locales_quest` SET `title_loc8`='Высокий дух',`offerrewardtext_loc8`='Наши величайшие воины и величайшие шаманы *фыркает* позавидовали бы твоей силе воли, |3-6($R).$B$BТеперь, зная, что иглогривам не остановить тебя, ты нанесешь еще больший урон племени Вздыбленной Щетины. *фыркает*' WHERE `entry`=5045;
