UPDATE `locales_quest` SET `title_loc8`='Даданга проголодалась!',`offerrewardtext_loc8`='Даданга с видимым удовольствием принюхивается к побегам.$B$BВ благодарность за лакомство она подталкивает к вам носом маленький коричневый сверток.' WHERE `entry`=5150;
