UPDATE `locales_quest` SET `title_loc8`='Камни осквернителей Плети',`offerrewardtext_loc8`='Поздравляю, $N! С гордостью вручаю тебе знак доблести Серебряного Рассвета.$B$BТолько настоящие герои и воины добра получают его. Мы ценим любые деяния, направленные против подлой Плети, но убийство одного из их лидеров заслуживает особого почтения!$B$BВо имя Рассвета, $Gбрат:сестра;!' WHERE `entry`=5404;
