UPDATE `locales_quest` SET `title_loc8`='Лекарство из охотничьих трофеев',`offerrewardtext_loc8`='Очень хорошо, вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, $N! Когда найдешь, исцеляй их при помощи моего целебного бальзама.' WHERE `entry`=5882;
