UPDATE `locales_quest` SET `title_loc8`='Путь охотника',`details_loc8`='Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.',`objectives_loc8`='Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта, что в Мулгоре.' WHERE `entry`=6065;
