UPDATE `locales_quest` SET `title_loc8`='Повелитель арены',`details_loc8`='Должно быть, стать повелителем арены не так просто! Быть может, пират-распорядитель на Арене Гурубаши, знает, в чем тут штука!',`objectives_loc8`='Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.',`offerrewardtext_loc8`='Арр, дорогуша! Одной безделушки недостаточно, чтобы стать мастером Арены! Пришло время проверить тебя на прочность.' WHERE `entry`=7810;
