UPDATE `locales_quest` SET `title_loc8`='Зернистое грузило',`offerrewardtext_loc8`='Вот это я понимаю! Не слишком тяжелые, но и вес чувствуется. Отлично подойдут для наращивания мышечной массы!$B$BТрижды спасибо, $N. А вот твой купон!' WHERE `entry`=7889;
