UPDATE `locales_quest` SET `title_loc8`='Тяжелый шлифовальный камень',`offerrewardtext_loc8`='Мои камушки! А какие тяжеленькие! Уже чувствую, как мышцы наполняются силой. Спасибо большое, $N!$B$BВот, возьми купоны – и смотри, не объедайся сладким! |3-6($C) вроде тебя должен держать себя в хорошей боевой форме!' WHERE `entry`=7890;
