UPDATE `locales_quest` SET `title_loc8`='Зеленые железные наручи',`offerrewardtext_loc8`='Благодарю тебя, $N. Эти камни нужны мне для ритуала, о котором я узнала из древней скрижали, найденной в глубоких джунглях Тернистой долины.$B$BТам говорится, что та, кто верно выполнит ритуал, станет обладательницей силы десяти тауренов!' WHERE `entry`=7891;
