UPDATE `locales_quest` SET `title_loc8`='Медный регулятор',`offerrewardtext_loc8`='Ага! Модуляторы! Супер!$B$BПока что я не могу тебе сказать, что мы возводим, но без модуляторов все просто развалится. Я твой должник, $N! Прими от меня этот купон и сердечную благодарность!' WHERE `entry`=7894;
