UPDATE `locales_quest` SET `title_loc8`='Светящаяся кровь скорпида',`offerrewardtext_loc8`='Чудесно, чудесно, $N! Спасибо тебе. Наварю краски и превращу вон ту кучу мусора в восхитительные сувениры!$B$BВот твои купоны – удачно отдохнуть!' WHERE `entry`=8222;
