UPDATE `locales_quest` SET `title_loc8`='Курочка с мятой',`details_loc8`='А, ты у нас сегодня вместо детишек, да? Я сказал бы, ты малость $Gстароват:старовата; конфетки выпрашивать...$B$BЧто же, за мое лакомство – мятную конфету Подгорода – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, им не обязательно их ЛЮБИТЬ... главное, что конфетку ты не получишь, пока не поквохчешь!$B$BНу что, |3-6($C), будешь квохтать или нет?! Пора отрабатывать лакомство!',`objectives_loc8`='Изобразите курицу для хозяина таверны Нормана и получите за это конфету Подгорода!',`offerrewardtext_loc8`='Ой, забавно! Просто здорово, $N! Вот твое угощение.$B$BВеселого Тыквовина!' WHERE `entry`=8354;
UPDATE `locales_quest` SET `EndText_loc8`='Изобразите курицу для хозяина таверны Нормана',`ObjectiveText1_loc8`='Изобразите курицу для хозяина таверны Нормана' WHERE `entry`=8354;
