UPDATE `locales_quest` SET `title_loc8`='Плата за леденцы',`details_loc8`='А, тебе нужны сладости! Ха-ха!$B$BНу, хотя ты и доброе дело делаешь, собирая сладости для детишек, так просто я тебя не отпущу. Есть у меня вкусные леденцы Гномрегана, и я отдам их детишкам... если ты изобразишь мне паровоз! Ха, вот это будет штука! За паровоз – целый леденец!$B$BТу-ту, |3-6($C)!',`objectives_loc8`='Изобразите паровозик для Талваша дель Кисселя.',`offerrewardtext_loc8`='Ой, забавно! Просто здорово, $N! Вот твое угощение.$B$BВеселого Тыквовина!' WHERE `entry`=8355;
