UPDATE `locales_quest` SET `title_loc8`='Тотем духов',`details_loc8`='Духи стихий здешних мест меня невзлюбили.$B$BТы знаешь о тотемах больше других, а мне без защитного тотема духов не обойтись. Стихии у нас уже есть, теперь нужно что-то более близкое к природе, первобытное.$B$BВ Западных Чумных землях можно добыть когти медведей и глаза пауков. Падальщики едят и тех, и других, поэтому у них в желудках может быть и то, и другое.',`objectives_loc8`='Принесите части тотема Духа Бат\'ре Стражу Ветра.',`offerrewardtext_loc8`='Отлично, $Gдружище:подруга;! Попробуем...' WHERE `entry`=8412;
