UPDATE `locales_quest` SET `details_loc8`='Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты.$B$BОднако если он действительно так могуществен, мне понадобятся предметы, собранные со смертельно опасных тварей...$B$BПрежде всего мне придется снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова племени Ярой Ненависти.$B$BИщи их в древних развалинах на северо-востоке Пустошей.',`objectives_loc8`='Принесите скальп тенелова Маурину Костолому в Пустошах.' WHERE `entry`=8458;
