UPDATE `locales_quest` SET `title_loc8`='Сапоги для стражей',`details_loc8`='Верховому подразделению Крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из Крепости Кенария.',`objectives_loc8`='Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.' WHERE `entry`=8540;
