UPDATE `locales_quest` SET `title_loc8`='Шлифовальные камни',`details_loc8`='У стражи Крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в Крепость Кенария.',`objectives_loc8`='Принесите 10 увесистых точильных каменей, 10 твердых шлифовальных камней и 10 тяжелых точильных каменей Вишу Коцусу, капитану стражи в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.' WHERE `entry`=8541;
