UPDATE `locales_quest` SET `title_loc8`='Орде не хватает бинтов из магической ткани!',`details_loc8`='Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю? Отлично! Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле "любой ценой". Хорошо бы свежие, но это совершенно не обязательно. Когда добудешь их, |3-6($C), возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили.',`objectives_loc8`='Принесите 20 бинтов из магической ткани госпоже Кэллоу в Аллею Духов Оргриммара.' WHERE `entry`=8607;
UPDATE `locales_quest` SET `CompletedText_loc8`='Вернитесь к госпоже Кэллоу в Оргриммар.' WHERE `entry`=8607;
