UPDATE `locales_quest` SET `title_loc8`='Большие связки фейерверков',`offerrewardtext_loc8`='Спасибо, $N. Вот инструкция по изготовлению больших сигнальных ракет. И пусть твое изделие принесет радость и удачу всем, кто будет на них любоваться.' WHERE `entry`=8881;
