UPDATE `locales_quest` SET `title_loc8`='Пусковая установка для связок фейерверков',`offerrewardtext_loc8`='Вот твой чертеж. Рассмотри его как следует и изучи...$B$BУдачи, $N. И пусть твои праздники посоперничают с самим Лунным фестивалем!' WHERE `entry`=8882;
