UPDATE `locales_quest` SET `title_loc8`='Уравнение стихий',`details_loc8`='Приветствую тебя, $Gстранник:странница;! Не ищешь ли ты работу? Плачу знаками отличия – их можно обменять на разные магические предметы у интендантов.$B$BСлушай, что мне нужно: принеси мне как можно больше средоточий стихий – сколько сможешь унести. Чем больше, тем лучше!$B$BСредоточия стихий можно найти у элементалей всех форм и размеров.',`objectives_loc8`='Принесите 30 средоточий стихий верховному магу Анджеле Досантос в Часовню Последней Надежды в Восточные Чумные земли.' WHERE `entry`=9128;
