UPDATE `locales_quest` SET `title_loc8`='Бегство из Катакомб',`details_loc8`='Тролли устроили мне засаду и теперь держат в этой клетке. Боюсь, они хотят принести меня в жертву! Помоги мне выбраться отсюда!$B$BЗамок на клетке несложный... просто с этой стороны мне до него не дотянуться. Пожалуйста, отведи меня в Анклав Странников. Капитан Гелиос наверняка наградит тебя, а уж я-то век тебя не забуду!',`objectives_loc8`='Проводите следопыта Лилату к капитану Гелиосу в Анклав Странников в Призрачных землях.' WHERE `entry`=9212;
