UPDATE `locales_quest` SET `title_loc8`='Легендарное боевое снаряжение – Чтимый Рассветом',`details_loc8`='Приветствую тебя, $Gбрат:сестра;. Желаешь ли обменять значки Серебряного Рассвета или значки Алого ордена на боевое снаряжение?$B$BНо помни, даже если тебя почитают в Серебряном Рассвете, эпические вещи будут стоить недешево!',`objectives_loc8`='За 45 знаков Рассвета и 45 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.' WHERE `entry`=9225;
