UPDATE `locales_quest` SET `title_loc8`='Свет в темных местах',`details_loc8`='Мы не единственные, кто справляет сегодня праздник, $N. Все создания, все народы возжигают пламя. Даже в самых темных уголках сегодня горят огни.$B$BЕсли хочешь увидеть их своими глазами, спустись в глубины. Отыщи костры, горящие в Стратхольме, Некроситете, у огров в Забытом Городе и в залах самого Пика Черной горы. Я буду ждать твоего возвращения.',`objectives_loc8`='Найдите костры, размещенные в Пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.' WHERE `entry`=9319;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Пламя пика Черной горы',`ObjectiveText2_loc8`='Пламя Забытого Города' WHERE `entry`=9319;
