UPDATE `locales_quest` SET `title_loc8`='Безжалостное коварство',`details_loc8`='*Лантрезор вручает вам ранец, набитый знаменами.*$B$BЭто – знамена огров Боевого Молота, которыми я недавно разжился в немалых количествах.$B$BОтправляйся в бастион Вечной Скорби, прямо к югу отсюда, и убей всех поганых прихвостней совета Теней, которые встретятся тебе на пути. Вонзи древко знамени в сердце каждого убитого защитника бастиона. Потом возвращайся ко мне.' WHERE `entry`=9927;
UPDATE `locales_quest` SET `RequestItemsText_loc8`='*Глаза Лантрезора широко раскрываются от изумления.*$B$BТы все $Gсделал:сделала?!',`ObjectiveText1_loc8`='Знамя огров Боевого Молота установлено' WHERE `entry`=9927;
