UPDATE `locales_quest` SET `title_loc8`='Вещественное доказательство',`details_loc8`='Твоя вылазка в бастион Вечной Скорби открыла нам новые возможности. Теперь у нас есть целая куча мертвых тел, с помощью которых можно инсценировать великую битву.$B$BОтправляйся на внутренний двор руин Веселого Черепа. Там горит костер. Убедись, что поблизости никого нет, и воспользуйся этим одеялом, чтобы подать дымовые сигналы. Когда мои огры увидят дым, они проникнут туда и живописно разложат повсюду трупы убитых защитников бастиона.$B$BЭто добьет наших врагов!',`objectives_loc8`='По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде найдите костер Боевого Молота во внутреннем дворе руин Веселого Черепа. С помощью мокрого шерстяного одеяла подайте дымовой сигнал ограм.',`offerrewardtext_loc8`='Давненько я ничего подобного не проворачивал! Спасибо за помощь, $N!' WHERE `entry`=9932;
UPDATE `locales_quest` SET `RequestItemsText_loc8`='Теперь ты понимаешь, почему меня невозможно победить?',`ObjectiveText1_loc8`='Трупы врагов живописно разложены' WHERE `entry`=9932;
