UPDATE `locales_quest` SET `title_loc8`='Разыскивается: Зорбо Советчик',`details_loc8`='Разыскивается живым или мертвым!$B$BЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Гарадар. При содействии разрушителей и шаманов преступник убил бессчетное количество орков. Зорбо вооружен, беспощаден и очень опасен.$B$BСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.$B$BУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Быккроку в Гарадаре.' WHERE `entry`=9939;
