UPDATE `locales_quest` SET `title_loc8`='Пожертвование – руническая ткань',`offerrewardtext_loc8`='Потрясающе! Эта ткань нам очень пригодится. Еще раз спасибо за помощь! Без тебя мы бы просто пропали.$B$BЕсли в будущем у тебя заведется еще лишняя рунная ткань, приноси и ее, пригодится. Уверяю тебя, твои добрые дела не пропадут втуне!' WHERE `entry`=10357;
