UPDATE `locales_quest` SET `title_loc8`='Финальный код',`details_loc8`='Они собирают еще одну мана-бомбу во дворе! Разведка сообщила мне, что финальный код от этой бомбы находится у Шарта Волдуна, который руководит этим проектом в Лагере Огнекрылов.$B$B$N, вам нужно вернуться туда и отобрать у него этот код. Шарт живет на пике самой высокой башни.$B$BКогда добудете код, найдите эту недособранную бомбу и отключите ее.$B$BТолько тогда Форт Камнеломов будет в безопасности.',`objectives_loc8`='Используйте финальный код, чтобы активировать мана-бомбу, как велела вам сержант Чани. После этого поговорите с Туки в Форте Камнеломов в лесу Тероккар.',`offerrewardtext_loc8`='У ВАС ВСЕ ПОЛУЧИЛОСЬ! ВЫ СПАСЛИ ФОРТ КАМНЕЛОМОВ!$B$BТеперь, когда их силы ослаблены, предводитель мертв, а бомба обезврежена, мы все сможем вздохнуть спокойно.$B$B$N, я никогда еще не встречал такой самоотверженности и такого... героизма! Пожалуйста, примите это в благодарность ото всех нас!' WHERE `entry`=10447;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Мана-бомба активирована',`ObjectiveText2_loc8`='Мана-бомба активирована' WHERE `entry`=10447;
