UPDATE `locales_quest` SET `title_loc8`='Возвращение домой',`details_loc8`='$R, |3-6($C)...$B$BДа, к нам недавно заходил один жрец из ваших, $N. Он сказал, что тебе пора возвращаться в Экзодар, чтобы встретиться с Кадмосом. Кажется, он советовал поторопиться, так что не стоит тянуть время.',`objectives_loc8`='Кадмос из Экзодара просит вас прийти и поговорить с ним.' WHERE `entry`=10534;
