UPDATE `locales_quest` SET `title_loc8`='История Нельтараку',`details_loc8`='У меня есть информация, которая тебе пригодится. Слушай внимательно, |3-6($R).',`objectives_loc8`='Поговорите с Нельтараку и выслушайте его историю.',`offerrewardtext_loc8`='Так ты поможешь нам?' WHERE `entry`=10814;
