UPDATE `locales_quest` SET `title_loc8`='Черн(окнижн)ый бизнес',`offerrewardtext_loc8`='Мне боязно даже прикасаться к этой нечестивой книге. Но нам придется ее читать, если мы хотим проникнуть в суть знаний, что в ней имеются, и выманить Скуллока из укрытия!' WHERE `entry`=10998;
