UPDATE `locales_quest` SET `title_loc8`='Испытание Наару: Магтеридон (QUEST FLAG)',`details_loc8`='Прежде чем наару признают тебя достойным, тебе предстоит пройти четыре испытания.$B$BОсталось лишь одно препятствие, $Gсмертный:смертная;. Собери армию побольше и отправляйся в логово Магтеридона в глубины Цитадели Адского Пламени. Пробейся в центральный чертог и убей гнусного сеятеля скверны!$B$BНаградой тебе станет ключ Урагана.',`objectives_loc8`='По заданию А\'дала из Шаттрата убейте Магтеридона.' WHERE `entry`=11116;
