UPDATE `locales_quest` SET `title_loc8`='<NYI>Расчистите место',`details_loc8`='Нам надо доставить в таверну Караноса кучу посылок. Причем быстро. Можешь взять моего скакового барана. Доставь хотя бы одну посылку. Времени у тебя немного – всего пять минут. Чем больше ты доставишь посылок, тем больше будет награда.',`objectives_loc8`='Доставьте в Каранос не меньше одной посылки. Чем больше доставить посылок, тем больше будет награда.' WHERE `entry`=11347;
