UPDATE `locales_quest` SET `title_loc8`='Скаковые бараны Хмельного фестиваля',`details_loc8`='Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.',`objectives_loc8`='Покажите штамп Полу Янтарлену у входа на территорию Хмельного фестиваля в Дун Мороге.' WHERE `entry`=11400;
