UPDATE `locales_quest` SET `title_loc8`='Учения пожарной бригады',`details_loc8`='Стражи смерти устроили учебный полигон за стенами города. Мы не можем допустить, чтобы дома Брилла продолжали гореть. Выполняйте свой долг и ступайте на учения пожарной бригады.$B$BИдите по дороге на запад мимо кладбища. Там увидите полигон.' WHERE `entry`=11449;
