UPDATE `locales_quest` SET `title_loc8`='Стишок Алисии',`details_loc8`='Привет, я тут написала стишок для моей подружки Кейли. Она любит гостить у Алдоров в Шаттрате. Ну, в Запределье, ты же знаешь?$B$BТы не отнесешь ей мои стишки? Моя мамочка говорит, что я еще слишком маленькая, чтобы ходить в Шаттрат!',`objectives_loc8`='Вас попросили отнести стишок Алисии Кайли Дак в Шаттрат в Запределье.',`offerrewardtext_loc8`='Какой трогательный стишок, спасибо!' WHERE `entry`=11451;
