UPDATE `locales_quest` SET `title_loc8`='Им рано умирать',`details_loc8`='Используйте охапку искусственных шкур, чтобы поймать в ловушки 8 звероловов Эрнестуэя по просьбе Зазы из лагеря Д.Э.Г.О.Ж. в Борейской тундре.',`objectives_loc8`='Используйте охапку искусственных шкур, чтобы поймать в ловушки 8 звероловов Эрнестуэя по просьбе Зазы из лагеря Д.Э.Г.О.Ж. в Борейской тундре.',`offerrewardtext_loc8`='Ты исполняешь волю Матери-Земли, $N, но не стоит упиваться своей победой! Мы обнаружили логово предводителя звероловов.' WHERE `entry`=11865;
