UPDATE `locales_quest` SET `title_loc8`='Обретение преимущества',`objectives_loc8`='Принесите 8 горстей пыли Пустоты эмиссару Мордину в Шаттрат.',`offerrewardtext_loc8`='Благодарю за помощь, $N. Любая помощь в час войны бесценна. Наши воины не должны упускать ни единого преимущества в этой войне.' WHERE `entry`=11875;
