UPDATE `locales_quest` SET `title_loc8`='Месть за бесчинства!',`details_loc8`='Эти так называемые охотники на магов явились сюда и уничтожили наше место отдыха.$B$BОтомсти за нас, или я позабочусь о том, чтобы вашу операционную базу заполонили духи умерших!',`objectives_loc8`='Убейте охотников на магов с Драконьего Погоста, ловчих из Садов Лунного Покоя, колдунов Волноловов и волшебников средоточия, общим числом 15, после чего возвращайтесь к Этениалу Тени Луны в Сады Лунного Покоя.',`offerrewardtext_loc8`='Очень хорошо, ты выполнил мою просьбу. $BСпасибо тебе, |3-6($R).' WHERE `entry`=12006;
UPDATE `locales_quest` SET `RequestItemsText_loc8`='Каким-то образом я чувствую, что ты еще не убил достаточное количество этих осквернителей!',`ObjectiveText1_loc8`='Убито сил синих драконов у Садов Лунного Покоя' WHERE `entry`=12006;
