UPDATE `locales_quest` SET `title_loc8`='Разыскивается: Гигантавр',`details_loc8`='Убейте Гигантавра и приходите за вознаграждением к капитану Горту в Молоте Агмара на Драконьем Погосте.',`objectives_loc8`='Убейте Гигантавра и приходите за вознаграждением к капитану Горту в Молоте Агмара на Драконьем Погосте.',`offerrewardtext_loc8`='Тебе удалось достать этого проклятого кобыльего сына, а? Ну, что ж, одной неприятностью для наших солдат в этой мерзлой пустыне меньше.' WHERE `entry`=12090;
