UPDATE `locales_quest` SET `title_loc8`='Сверток для Кренны',`details_loc8`='Вот, $Gдружище:подруга;. Давай-ка отнесем эти шкуры Кренне и посмотрим, как она отреагирует.$B$BОчень надеюсь, что она ничего не заметит.',`objectives_loc8`='Отнесите связку шкур Кренне в Крепость Завоевателей.',`offerrewardtext_loc8`='За кого ты меня принимаешь? От этих шкур за километр пахнет мукой!$BХочешь оскорбить всю Орду?' WHERE `entry`=12178;
UPDATE `locales_quest` SET `RequestItemsText_loc8`='Ты хоть знаешь, с кем разговариваешь?' WHERE `entry`=12178;
