UPDATE `locales_quest` SET `title_loc8`='Бойцовская яма: кровь и железо',`details_loc8`='Одержите победу над Кроворжавом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.',`objectives_loc8`='Одержите победу над Кроворжавом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.',`offerrewardtext_loc8`='Эта металлическая бочка едва тебя не задавила! Честное слово, у меня чуть сердце из груди не выскочило!' WHERE `entry`=12429;
