UPDATE `locales_quest` SET `title_loc8`='Бойцовская яма: смерть близка',`details_loc8`='Одержите победу над Хоргренном Страшным Расколом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.',`objectives_loc8`='Одержите победу над Хоргренном Страшным Расколом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.',`offerrewardtext_loc8`='Ишь, какой ловкий!  Быстро ты уделал этого бешеного орка.$BСтавки были семь к одному против тебя, так что мы неплохо заработали!' WHERE `entry`=12430;
