UPDATE `locales_quest` SET `title_loc8`='Тролльский дозор: животворящее тепло',`details_loc8`='Да уж, приятного в этом мало, но долг есть долг.$B$BУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$B$BИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$B$BЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$B$BСобери нам дров для костра, и мы будем очень тебе благодарны.',`objectives_loc8`='Принесите капитану Гронделю в Драк\'Агал 20 кусков древесины высохшего колючника.',`offerrewardtext_loc8`='Спасибо, $N. Большое спасибо.$BТеперь иди к капитану Арнату. На запад, прямо за этим холмом.' WHERE `entry`=12585;
