UPDATE `locales_quest` SET `title_loc8`='Подрывные работы',`details_loc8`='Умно...$B$BМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$B$BИ теперь мы оказались зажаты между двумя нерубскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$B$BНаша первоочередная задача – помешать этим двум армиям получить подкрепление. Надо засыпать тоннели.$B$BВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.',`objectives_loc8`='По заданию капитана Руперта из Драк\'Сотры обрушьте 5 нерубских тоннелей с помощью фугасных гранат.',`offerrewardtext_loc8`='Угроза еще существует, но то, что ты сделал, существенно замедлит продвижение неприятеля.$BКапитану Гронделю в Драк\'Агале наверняка требуется твоя помощь.$BПрощай, $N.' WHERE `entry`=12598;
