UPDATE `locales_quest` SET `title_loc8`='На помощь заставе',`details_loc8`='Буквально пару секунд назад я заметила сигнальную вспышку над восточными лесами.$B$BЭто может означать только одно: у рыцарей Серебряной заставы что-то случилось, и явно что-то не очень приятное.$B$BЯ не могу бросить пост и уйти, |3-6($R), а ты можешь. При первой удобной возможности отправляйся туда, к командиру Фальштаву, и помоги им, чем сможешь.',`objectives_loc8`='По поручению Датуры Кровавой Розы поговорите с командиром Фальштавом на Серебряной заставе.',`offerrewardtext_loc8`='Да, нам нужна помощь, |3-6($C), так что ты можешь быть нам $Gполезным:полезной;.' WHERE `entry`=12795;
UPDATE `locales_quest` SET `title_loc8`='Магическое королевство Даларан',`details_loc8`='Здравствуй, $N! Ты еще не $Gслышал:слышала; о том, что Кирин-Тор перенес наш славный город сюда, в Нордскол?$B$BИстинная правда; Даларан больше не найти на берегах озера Лордамер. Теперь он волшебным образом парит над лесом Хрустальной Песни.$B$BПожалуй, ты уже $Gготов:готова; совершить путешествие в наш город. Обратись ко мне, и я прочитаю заклинание телепортации.$B$BКак прибудешь на место, найди верховного мага Селиндру и передай ей мой перстень в знак того, что ты $Gприбыл:прибыла; по моему поручению.',`objectives_loc8`='Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана.',`offerrewardtext_loc8`='Отнесите печатку Кирин Тор верховному магу Селиндре к Аметистовым Вратам Даларана.' WHERE `entry`=12796;
