UPDATE `locales_quest` SET `title_loc8`='Семена Хаоса',`details_loc8`='Полезная вещь, не правда ли? Тебе отлично удалось ослабить их оборону, |3-6($C). Теперь мы можем отправить в наступление основные силы.$B$BПлан прост: мы уничтожаем все, что движется, прорываемся вовнутрь и, пользуясь всеобщим замешательством, похищаем нужную информацию.$B$BСкажешь, когда будешь $Gготов:готова;. Я дам тебе грифона-скелета.',`objectives_loc8`='По указанию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 80 солдат нежити в Саронитовом карьере. Попросите у него грифона-скелета.',`offerrewardtext_loc8`='Да там защита – одно название. Проще не бывает.' WHERE `entry`=13172;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Уничтожено нежити в Саронитовом карьере' WHERE `entry`=13172;
