UPDATE `locales_quest` SET `title_loc8`='Беспощадным пощады не будет',`details_loc8`='Добро пожаловать в крепость Ледяных Оков, $N. Твое задание будет очень простым. Одержи победу над десятью представителями Орды. А теперь ступай! Принеси победу Альянсу!',`objectives_loc8`='Убейте 10 игроков Орды по приказу командира Заннета из крепости Ледяных Оков.',`offerrewardtext_loc8`='Великолепно! Ты – $Gодин:одна; из величайших воинов Альянса!' WHERE `entry`=13177;
