UPDATE `locales_quest` SET `title_loc8`='Убить всех и каждого!',`details_loc8`='Добро пожаловать в крепость Ледяных Оков, $N. Вождь Гаррош требует лишь одного: убить их всех!$B$BВозвращайся ко мне, когда десять самых сильных воинов Альянса будут мертвы.',`objectives_loc8`='Убейте 10 игроков Альянса по приказу командира Дардоша с Озера Ледяных Оков.',`offerrewardtext_loc8`='Лок\'тар! Орду ждет победа!' WHERE `entry`=13178;
