UPDATE `locales_quest` SET `title_loc8`='Остановка осады',`details_loc8`='Я слышать их! Альянс скоро прийти. Уничтожь три осадных машины Альянса и возвращайся к Мурпу.',`objectives_loc8`='Уничтожьте 3 осадных машины Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков.',`offerrewardtext_loc8`='Отличная работа. Жаль, Мурпа рядом не было, он бы тебе помог.' WHERE `entry`=13185;
