UPDATE `locales_quest` SET `title_loc8`='Остановка осады',`details_loc8`='Рано или поздно крепость будет осаждена силами Орды. Уничтожь три их осадных машины и возвращайся ко мне.',`objectives_loc8`='Уничтожьте по приказу главного подрывника Легосо из крепости Ледяных Оков 3 осадных машины Орды.',`offerrewardtext_loc8`='Отлично. Это должно существенно ослабить их атаку.' WHERE `entry`=13186;
