UPDATE `locales_quest` SET `title_loc8`='Рывок',`details_loc8`='<Воин-матик NX-01 включается в оперативный режим.>$B$BОбнаружен босс $N. Я Воин-матик NX-01.$B$BОпустите монету, чтобы получить сеанс массажа или обучиться приему "Рывок". После изучения приема потренируйтесь на манекене, что стоит поблизости.',`objectives_loc8`='Поговорите с Воином-матиком NX-01 и обучитесь приему "Рывок", после чего опробуйте его на тренировочном манекене.' WHERE `entry`=14013;
