UPDATE `locales_quest` SET `title_loc8`='Опознание останков',`details_loc8`='Неповрежденный зуб кракена – это действительно редкая находка. Наверняка она заинтересует Крестоносца Серебристый Рассвет из Серебряного павильона.',`objectives_loc8`='Отнесите зуб кракена Крестоносцу Серебристый Рассвет в Серебряный павильон.' WHERE `entry`=14095;
