UPDATE `locales_quest` SET `title_loc8`='Эвакуация Торговой площади',`details_loc8`='Теперь здесь стало небезопасно – даже родные стены не могут защитить от беды.$B$BМы пытаемся не пустить воргенов в дома, но их слишком много, и за всеми невозможно уследить.$B$BПомоги нам эвакуировать жителей в тюремный квартал – армия моего отца сможет лучше их защитить.',`objectives_loc8`='Помогите эвакуировать людей из 3 домов.' WHERE `entry`=14098;
