UPDATE `locales_quest` SET `title_loc8`='Голова змеи',`details_loc8`='В офицерском лагере нас учат всегда отрубать змее голову. Не очень умный совет, учитывая то, что мы никогда не имели дела со змеями, но сейчас в нем есть смысл.$B$BВозьми здесь людей и убей лорда Кассара.',`objectives_loc8`='Убейте лорда Кассара в храме Зин-Малор.' WHERE `entry`=14484;
