UPDATE `locales_quest` SET `title_loc8`='Нужен Тикер',`details_loc8`='Наш лучший подрывник, Тикер, закреплен за морским отрядом. У него взрывчатки НАМНОГО больше, чем нужно, чтобы взорвать все рунические камни в руинах.$B$BВсе, что от тебя требуется, это отвести его туда и прикрыть. С остальным он разберется сам.',`objectives_loc8`='Приведите Тикера в руины и прикройте его, пока он прикрепляет бомбы к 3 руническим камням Бича Злобы.' WHERE `entry`=14485;
