UPDATE `locales_quest` SET `title_loc8`='К оружию! Ущелье Песни Войны',`details_loc8`='Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`='Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`offerrewardtext_loc8`='Орда в долгу перед тобой, $N. Твой народ гордится твоей отвагой на защите наших земель.' WHERE `entry`=24217;
