UPDATE `locales_quest` SET `title_loc8`='ИСКЛЮЧЕНО',`details_loc8`='Битва с Ордой не знает границ, $N. Даже в Запределье старая ненависть может вспыхнуть с новой силой, склонив чаши весов войны в пользу одного из противников.$B$BОтправляйся в Око Бури и убедись, что Альянс одержит верх в Запределье, как и по всему Азероту.',`objectives_loc8`='Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.' WHERE `entry`=24227;
