UPDATE `locales_quest` SET `title_loc8`='Боевой крик',`details_loc8`='Я сам всего лишь ученик, $N, но в знак благодарности я тоже могу поделиться с тобой знаниями.$B$BРазреши мне научить тебя, как трансформировать твою внутреннюю ярость в могущественный боевой крик.',`objectives_loc8`='Поговорите с Храбрецом Острым Рогом и выучите боевой крик.' WHERE `entry`=24466;
