UPDATE `locales_quest` SET `title_loc8`='Инструктор Разувий должен умереть!',`details_loc8`='Инструктор Разувий напыщенно вышагивает по Военному кварталу Наксрамаса. Говорят, что только рыцарь смерти, лично обученный этим воином, может устоять против его меча.$B$BДокажи, что это не так. Совет Шести приговорил Разувия к смерти!',`objectives_loc8`='Убейте Инструктора Разувия.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.',`offerrewardtext_loc8`='Очень хорошо, |3-6($C). Со смертью Разувия военная машина Плети в Наксрамасе застопорится.' WHERE `entry`=24582;
