UPDATE `locales_quest` SET `title_loc8`='Лоскутик должен умереть!',`details_loc8`='Лоскутик, также известный как "воплощение войны", – самое совершенное из созданных Плетью поганищ. Он нанес огромный урон нашим войскам в Драконьем Погосте.$B$BСобери своих союзников и отправляйся в Квартал Мерзости Наксрамаса. Уничтожь это чудовище.$B$BСовет Шести приговорил Лоскутика к смерти!',`objectives_loc8`='Убейте Лоскутика.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.',`offerrewardtext_loc8`='Теперь Лоскутик не будет являться детишкам в кошмарах.' WHERE `entry`=24583;
