UPDATE `locales_quest` SET `title_loc8`='Острокрылая должна умереть!',`details_loc8`='Обычно Острокрылая не покидает пределов Гигантской кузни Ульдуара, но недавно ее видели за границами города титанов. Она обрушивала огненный шквал на окрестные земли.$B$BСудьба праматери была нелегка, но сейчас она представляет угрозу всему Нордсколу. Совет Шести приговорил Острокрылую к смерти!',`objectives_loc8`='Убейте Острокрылую.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.' WHERE `entry`=24586;
