UPDATE `locales_quest` SET `title_loc8`='Очищение Кель\'Делара',`details_loc8`='Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.',`objectives_loc8`='Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.',`offerrewardtext_loc8`='Это невероятно, $N. Ты действительно $Gсовершил:совершила; невозможное! Все кель\'дорай знают о Талориене Искателе Рассвета и легендарном Кель\'Деларе, но никто и не думал, что меч может быть восстановлен.' WHERE `entry`=24595;
