UPDATE `locales_quest` SET `title_loc8`='Дар королю Штормграда',`details_loc8`='Хочешь создать чудесный браслет-оберег для короля Штормграда? Он будет в восторге.$B$BА у тебя есть набор собирателя прелестных оберегов?',`objectives_loc8`='Подарите чудесный браслет-оберег королю Штормграда Вариану Ринну.' WHERE `entry`=24597;
