UPDATE `locales_quest` SET `title_loc8`='Азы мастерства: поражение цели',`details_loc8`='Ну ладно, $Gдружище:подруга;. Начнем с азов. Посмотрим, как ты владеешь этим своим оружьицем.$B$BПопробуй-ка разнести в щепки вон те манекены-тики. Не торопись. Делай, как получится. А я посмотрю, как ты дерешься и что с этим можно сделать.',`objectives_loc8`='Уничтожьте 6 манекенов-тики.' WHERE `entry`=24639;
