UPDATE `locales_quest` SET `title_loc8`='Кристалл-губитель',`offerrewardtext_loc8`='Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.' WHERE `entry`=24729;
