UPDATE `locales_quest` SET `title_loc8`='Сдавайся, не то хуже будет!',`details_loc8`='$N, тебе с Тузом нужно захватить маленьких наг и превратить их в средство убеждения. Главарь наг должен понять, что пора сдаваться.$B$BАс знает, куда идти – в южную часть развалин... следуй за ним.',`objectives_loc8`='Разберитесь с главарем наг в руинах Вайш\'элана.' WHERE `entry`=24868;
