UPDATE `locales_quest` SET `title_loc8`='Перевербовка',`details_loc8`='Мы планировали заслать агента в Культ Проклятых, чтобы получить возможность следить за действиями Короля-лича напрямую, но мы… недооценили силу Артаса и его приближенной, Леди Смертный Шепот.$B$BВ итоге, один из наших людей, Дарнаван, был обращен на их сторону.$B$BЕсли ты собираешься расчистить путь в молельню, прошу тебя, поищи Дарнавана. Если тебе удастся вернуть его живым, мы постараемся устранить последствия промывки мозгов.',`objectives_loc8`='Убейте Леди Смертный Шепот, сохранив жизнь Дарнавану.' WHERE `entry`=24869;
