UPDATE `locales_quest` SET `title_loc8`='Топая по лужам',`details_loc8`='Ситуация такова: если мы хотим упрочить положение картеля Трюмных Вод на рынке Прибамбасска, необходимо начать предоставлять потребителям услуги.$B$BНовый берег – отличное место для развития нашего бизнеса, однако в море есть и огромные морские великаны, так что цена недвижимости там невелика.$B$BОтправляйся к отмелям на юге от города и убей как можно больше великанов, а я поделюсь с тобой комиссионными с некоторых сделок.',`objectives_loc8`='Убейте 8 приливных странников.' WHERE `entry`=24907;
