UPDATE `locales_quest` SET `title_loc8`='Помни о Свете',`details_loc8`='Магтур слабеет с каждым мигом, $N. Мое снадобье готово… оно должно помочь. Просто обязано!$B$BТы так много $Gсделал:сделала; для нас обоих. Я был бы признателен, если бы ты $Gпочтил:почтила; нас своим присутствием в последние минуты жизни Магтора.',`objectives_loc8`='Поддержите анахорета Авууна в последние минуты жизни Магтура.' WHERE `entry`=24913;
