UPDATE `locales_quest` SET `title_loc8`='Личное имущество',`details_loc8`='На ящике не видно ни петель, ни замка. Если бы не шум перекатывающихся внутри предметов, его вполне можно было бы принять за цельный кусок металла. $B$BЕдинственным, кто смог бы его открыть, является верховный лорд Могрейн.',`objectives_loc8`='Отнесите запечатанный сундук верховному лорду Дариону Могрейну в Цитадель Ледяной Короны.',`offerrewardtext_loc8`='Вот, пожалуйста, $N.' WHERE `entry`=24914;
