UPDATE `locales_quest` SET `title_loc8`='Дотла!',`details_loc8`='Я провела тщательную оценку недвижимости здесь и, к сожалению, ее рыночная стоимость ниже даже минимального приемлемого уровня. Придется заняться восстановлением.$B$BТебе повезло – я кое-что знаю о поджогах. Надеюсь, ты тоже! Подожжешь эти отвратительные ветхие лачуги с помощью абсолютно безопасных в использовании бутылок горючего рома.$B$BСтарайся держаться с подветренной стороны.',`objectives_loc8`='Подожгите лачуги на северо-западе, северо-восторе и юго-западе.' WHERE `entry`=24928;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Лачуга на северо-западе',`ObjectiveText2_loc8`='Лачуга на юго-западе' WHERE `entry`=24928;
