UPDATE `locales_quest` SET `title_loc8`='Расставить точки над Ингви',`details_loc8`='Правитель Умлота Ингви обладает слишком большой властью. Его нельзя оставлять в живых. Сейчас он торчит за навесным мостом на западе деревни и не переставая несет какую-то пигмейскую околесицу.$B$BУбей его, пока он не натравил на нас всю деревню.$B$BЭто будет легче легкого!',`objectives_loc8`='Убейте Ингви.' WHERE `entry`=24929;
