UPDATE `locales_quest` SET `title_loc8`='Попутное дело',`details_loc8`='Если король Седогрив просит тебя рискнуть жизнью ради предателя – это твое дело.$B$BТолько сделай по пути что-нибудь полезное – убей несколько вшивых шавок.',`objectives_loc8`='Убейте 5 воргенов из стаи Кровавых Клыков.' WHERE `entry`=24930;
