UPDATE `locales_quest` SET `title_loc8`='Патрулирование Разлива Строптивой',`details_loc8`='Мой пост здесь, на башне, $N, и я не могу покинуть его. Но мне нужен кто-то, способный помочь людям, оказавшимся в западне наводнения.$B$BМогу ли я на тебя рассчитывать?',`objectives_loc8`='Отправляйтесь к Разливу Строптивой и помогите тем, кого вы видели в подзорную трубу.' WHERE `entry`=25188;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Помогите престарелой Текле.',`ObjectiveText2_loc8`='Помочь Ярагану' WHERE `entry`=25188;
