UPDATE `locales_quest` SET `title_loc8`='Оскверненная земля',`details_loc8`='Скальные великаны Фераласа – это продолжение самой земли, $N. Когда природе ничего не угрожает, они ведут себя как добрые защитники и мирные стражи.$B$BНо теперь лес заражен, и они вместе с ним.$B$BОднако если они заражены, то скоро набросятся на фауну и своих же собратьев, неся великие разрушения. Нужно уничтожить всех зараженных великанов, какие тебе только встретятся.',`objectives_loc8`='Убейте 7 зараженных скальных великанов.' WHERE `entry`=25241;
