UPDATE `locales_quest` SET `title_loc8`='Решающее противостояние',`details_loc8`='$N, вот и все! Тралл сейчас на верфи Галливикса сражается с торговым принцем!$B$BДавай, запрыгивай в свою идеальную футбомбную униформу и живо езжай туда!',`objectives_loc8`='Забирайтесь в идеальную футбомбную униформу, а потом разберитесь с торговым принцем Галливиксом.' WHERE `entry`=25251;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Лучшая футбомбная униформа',`ObjectiveText2_loc8`='С торговым принцем Галливиксом покончено' WHERE `entry`=25251;
