UPDATE `locales_quest` SET `title_loc8`='Тренировка ловкости: беги со всех ног!',`details_loc8`='Перед тем как мы продолжим, нам надо привести тебя в форму.$B$BПреданность древним богам не спасет тебя, когда за тобой будет мчаться какой-нибудь зеленый дракон. Тебе надо быть $Gлегким:легкой; на подъем, если ты понимаешь, о чем я.$B$BХватит болтать. Призовем тебе тренера… твоя задача – бегать от него, не покидая лагерь.$B$BВперед!',`objectives_loc8`='Бегайте от пылающего тренажера в Кузне Мольбы в течение 1 минуты.' WHERE `entry`=25499;
