UPDATE `locales_quest` SET `title_loc8`='Подготовка почвы',`details_loc8`='Верховный друид попросил меня расставить огненных стражей по периметру. Когда мы приведем их в действие, то защитим эту область от нападений элементалей огня, принесших разрушение в нашу долину.$B$BСтражи также защитят и подготовят почву, как того хочет Хамуул.$B$BПора браться за дело. Найди одного из пяти стражей огня, отмеченных мною на карте, активируй его и защити от нападений, пока его магия не наберет силу. Это займет не более минуты.',`objectives_loc8`='Активируйте и защитите огненного стража.' WHERE `entry`=25502;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Огненная защита задействована',`ObjectiveText2_loc8`='Огненная защита защищена' WHERE `entry`=25502;
