UPDATE `locales_quest` SET `CompletedText_loc8`='Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.' WHERE `entry`=25513;
UPDATE `locales_quest` SET `title_loc8`='Освобождение от пут',`details_loc8`='Из глубин...$BОбители тьмы и огня.$BУдерживают меня в забытьи.$B$BЯ томлюсь в путах, |3-6($R).$B$BТени мелькают в столпах огня рядом со мной. Уничтожь их.$BТогда я вновь обрету свободу.',`objectives_loc8`='Выведите из строя два жезла порабощения, удерживающих Тортоллу.' WHERE `entry`=25514;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Первый жезл порабощения выведен из строя',`ObjectiveText2_loc8`='Второй жезл порабощения выведен из строя' WHERE `entry`=25514;
