UPDATE `locales_quest` SET `title_loc8`='Драка в баре!',`details_loc8`='Ну все, эти недотепы-гномы, которых можно за кружку с элем спрятать, напросились!$B$BОтправляйся-ка в Бар гоночной баржи, закажи бутылку грога и врежь кому-нибудь из них промеж глаз!$B$BОбъясни им, $N, что больше мы их высокомерие терпеть не намерены!',`objectives_loc8`='Начните драку в баре!' WHERE `entry`=25518;
