UPDATE `locales_quest` SET `title_loc8`='Дети Тортоллы',`details_loc8`='Мои дети...$B…лежат внизу.$BСреди ила и песка.$B$BИх пытаются осквернить.$BЗаполнить их панцири тьмой.$B$BУмертви тех, кто повинен в этом.$BУничтожь осквернителей.$BСпаси моих детей...',`objectives_loc8`='Убейте 6 осквернителей глубин, нападающих на яйца Тортоллы в Пепельном озере.' WHERE `entry`=25519;
