UPDATE `locales_quest` SET `title_loc8`='Пробуждение древнего бога',`details_loc8`='Я дремал в целительном иле Хиджала.$BЯ спал до тех пор, пока не открылся разлом.$BПриход осквернителей стал для меня неожиданностью.$B$BТеперь я готов, |3-6($R).$B$BЯ и мои дети. Нас сложно разгневать.$BОднако страшен наш гнев.$B$BСкажи тем, кто прислал тебя, что мы готовы к войне.$B$BМы очистим гору от осквернителей.',`objectives_loc8`='Вернитесь к верховному друиду Хамуулу Руническому Тотему, находящемуся в Святилище Малорна на горе Хиджал.' WHERE `entry`=25520;
