UPDATE `locales_quest` SET `title_loc8`='На оборону дилижанса... то есть лодки!',`details_loc8`='С пожарами мы справились, но пираты Южных морей по-прежнему готовят нападение на гоночную баржу!$B$B$N, придется тебе снова отправляться к Гризнаку за лодкой. Расстреляй побольше пиратов из пушки, пока не поздно!',`objectives_loc8`='Потопите 15 шлюпок Южных морей.' WHERE `entry`=25562;
