UPDATE `locales_quest` SET `title_loc8`='Заставь пушки замолчать',`details_loc8`='Теперь нужно что-то сделать с этими проклятыми пушками на обрывах к востоку!$B$BБудь душкой, садись в лодку и отправляйся к Укреплению Южных морей. Наверху увидишь палящие по нам пушки.$B$BПираты ни шиша не смыслят в инженерном деле. Так что тебе не составит труда чем-нибудь закупорить эти пушки, чтобы они взорвались ко всем чертям.',`objectives_loc8`='Уничтожьте 8 пушек укрепления.' WHERE `entry`=25586;
