UPDATE `locales_quest` SET `title_loc8`='Найдите мне убежище!',`details_loc8`='Прошу тебя, |3-6($R)! Ты $Gдолжен:должна; мне помочь!$B$BЯ едва уцелела после той передряги с нагами, акулами и жутким монстром, напавшим на наш корабль.$B$BВон там на вид безопасная пещера, но я боюсь идти туда – вдруг в ней дышать нечем?$B$BНе $Gмог:могла; бы ты проверить?',`objectives_loc8`='Исследуйте Пещеру Контрабандистов в лесу Келп\'тар и сообщите Адарре, что там безопасно.' WHERE `entry`=25587;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Пещера контрабандистов обследована',`ObjectiveText2_loc8`='Адарра получила сигнал' WHERE `entry`=25587;
UPDATE `locales_quest` SET `CompletedText_loc8`='Поговорите с Адаррой в Пещере контрабандистов.' WHERE `entry`=25587;
UPDATE `locales_quest` SET `title_loc8`='Частичная расплата',`details_loc8`='Пришло время с ними поквитаться. Мне кажется, они это заслужили! Они же заперли меня в сортире и оставили тонуть!$B$BЯ щедро тебе заплачу, если ты отправишься в Укрепление Южных морей и отомстишь за меня.',`objectives_loc8`='Зарубите 15 пиратов в Укреплении Южных морей.' WHERE `entry`=25588;
