UPDATE `locales_quest` SET `title_loc8`='Частичная расплата',`details_loc8`='Пришло время с ними поквитаться. Мне кажется, они это заслужили! Они же заперли меня в сортире и оставили тонуть!$B$BЯ щедро тебе заплачу, если ты отправишься в Укрепление Южных морей и отомстишь за меня.',`objectives_loc8`='Зарубите 15 пиратов в Укреплении Южных морей.' WHERE `entry`=25589;
