UPDATE `locales_quest` SET `title_loc8`='Докопаться до истины' WHERE `entry`=25603;
UPDATE `locales_quest` SET `title_loc8`='Докопаться до истины',`details_loc8`='На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.',`objectives_loc8`='Отнесите загадочное устройство в Штормград, Стальгорн, Экзодар или Дарнас и покажите его представителю Служителей Земли.' WHERE `entry`=25604;
