UPDATE `locales_quest` SET `title_loc8`='Убрать Тони Два Клыка',`details_loc8`='Это не сокровище, а груда мусора, но эти безмозглые громилы наверняка не заметят разницы. Недоумки-огры!$B$BВот что мы сделаем... иди в Укрытие адмирала и раскидай это "сокровище" перед ограми, чтобы их отвлечь. А затем сразись с Тони Два Клыка.$B$BПолучишь ключ от клетки легко!',`objectives_loc8`='Раздобудьте ржавый ключ от клетки.' WHERE `entry`=25627;
