UPDATE `locales_quest` SET `CompletedText_loc8`='Поговорите с Эрунаком в Конце отмели.' WHERE `entry`=25794;
UPDATE `locales_quest` SET `title_loc8`='Возвращение в святилище',`details_loc8`='Яйцо Авианы было доставлено в святилище, и сейчас оно находится в безопасности. Чолуна должна знать, что делать дальше.$B$BЯ закончу кое-какие наши дела и присоединюсь к тебе позже.',`objectives_loc8`='Вернитесь к Чолуне в святилище Авианы на горе Хиджал.' WHERE `entry`=25795;
