UPDATE `locales_quest` SET `title_loc8`='На защиту бура',`details_loc8`='Лично я с пустыми руками отсюда не уйду! Ты со мной?$B$BБьюсь об заклад, тебе не терпится узнать, что вон в том огромном ящике. Что ж, момент истины настал. Доставь одну из наших буровых установок к нефтяным пластам и добудь нам немножко сырца.$B$BКентавры наверняка попытаются на тебя напасть. Так что защищай бур до тех пор, пока тот не выкачает бочку-другую нефти.',`objectives_loc8`='Защитите оборудование для добычи нефти.' WHERE `entry`=25798;
