UPDATE `locales_quest` SET `title_loc8`='Кровь и гром!',`details_loc8`='Пора браться за дело, |3-6($R)!$B$BБудем защищать корабль до последнего. Пусть змеюки в следующий раз дважды подумают, прежде чем сюда соваться.$B$BЗа Орду!',`objectives_loc8`='Помогите легионеру Назгриму защитить Серпантин Бессмертного.' WHERE `entry`=25949;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Оборона Серпантина Бессмертного завершена' WHERE `entry`=25949;
