UPDATE `locales_quest` SET `title_loc8`='Знаменательный день для Азражара',`details_loc8`='$N, змеюки снова на нас поперли. Так что давай дуй обратно на северо-запад, к Гряде Глубинных Плавников, и наведи там шороху. Грохни их главного и воткни в его труп наше знамя.$B$BПусть они там от страха обделаются и уберутся куда подальше, поджав хвосты... или щупальца... или что там у них...',`objectives_loc8`='Воткните знамя Альянса в труп призывателя глубин Азражара.' WHERE `entry`=25977;
