UPDATE `locales_quest` SET `title_loc8`='Утихомирить волны',`details_loc8`='Стихии в смятении, |3-6($C). Катаклизм потревожил давно дремлющих духов воды озера Хельмово Ложе, что к югу отсюда. Они злы, растеряны и совершенно не желают внимать моим просьбам.$B$BЯ испробовал все, что знал, чтобы успокоить их и убедить перестать набрасываться на горных пехотинцев сержанта.$B$BМне больно говорить это, но другого выхода нет – мы должны убить элементалей.',`objectives_loc8`='Убейте 6 озерных волногонов в озере Хельмово Ложе.' WHERE `entry`=25979;
