UPDATE `locales_quest` SET `title_loc8`='Знаменательный день для Азражара',`details_loc8`='$N, наги снова готовятся к атаке. Возвращайся на северо-запад к Гряде Глубинных Плавников, убей их генерала, призывателя глубин Азражара, и воткни в его труп наше знамя.$B$BЭто устрашит наг, и они уберутся восвояси, поджав хвосты.',`objectives_loc8`='Воткните знамя Орды в труп призывателя глубин Азражара.' WHERE `entry`=25980;
