UPDATE `locales_quest` SET `title_loc8`='Это не маски',`details_loc8`='$N, эти кальмарообразные демоны... они присасываются к головам жаблинов и превращают их в послушных рабов! Совсем не хочется, чтобы эти твари добрались сюда!$B$BЯ вот думаю... может быть, сплаваешь на северо-запад к Гряде Глубинных Плавников или на берег Сира\'кесс и принесешь мне штук шесть голов этих безжалостных тварей? Желательно – мертвых.',`objectives_loc8`='Добудьте 6 голов безжалостных.' WHERE `entry`=25982;
