UPDATE `locales_quest` SET `title_loc8`='Прекрасная маскировка',`details_loc8`='У меня идея, как замаскироваться. Отлично выйдет, $N! Берешь труп безжалостной твари и надеваешь себе на голову.$B$BДа, я все понимаю... но она же дохлая, так что тебе ничего не будет. Ну, разве что пару дней повоняешь тухлятиной, но для пользы же дела!$B$BПопробуем?',`objectives_loc8`='Посмотрите, что будет, если надеть на голову мертвого Безжалостного.' WHERE `entry`=25988;
