UPDATE `locales_quest` SET `title_loc8`='Уничтожение скверны',`details_loc8`='Служители Земли, хотят, чтобы мы поубивали за них. В Жгучем провале завелись какие-то безликие демоны, которые оскверняют природу.$B$BОтправляйся туда и займись оскверненными существами.',`objectives_loc8`='Уничтожьте несколько угрей-сокрушителей, глубоководных прилипал или ловцов провала – в общей сложности 8 тварей.' WHERE `entry`=26071;
