UPDATE `locales_quest` SET `title_loc8`='Зарядка тотема',`details_loc8`='Бери мой тотем и отправляйся в Жгучий провал. Там зарядишь его энергией умирающих безликих. Тотем впитает их энергию и не даст вернуться туда, откуда они появились.$B$BКогда тотем полностью зарядится, возвращайся, и мы с его помощью выманим из глубин их предводителя.',`objectives_loc8`='Уничтожьте 5 безликих сквернителей в непосредственной близости от улавливающего тотема.' WHERE `entry`=26072;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Энергия безликих сквернителей собрана' WHERE `entry`=26072;
