UPDATE `locales_quest` SET `title_loc8`='Защита Донных зарослей',`details_loc8`='Ты $Gвидел:видела; наверху шпионов? Это плохо... Такого допускать нельзя!$B$BВозвращайся в Донные заросли и уничтожь их, прежде чем они проникнут в наше убежище.',`objectives_loc8`='Убейте 7 морских разведчиков Альянса в Донных зарослях.' WHERE `entry`=26125;
