UPDATE `locales_quest` SET `title_loc8`='Теперь они не переродятся!',`details_loc8`='ЧТОБЫ... ИХ ОСТАНОВИТЬ... НАДО УНИЧТОЖИТЬ... ДРЕВНИЕ КАНАЛЫ.$B$BПО НИМ ОНИ ВЫКАЧИВАЮТ... ИЗ МЕНЯ... ЭНЕРГИЮ... И СОЗДАЮТ... ПЕРЕРОЖДЕННЫХ.$B$BСРАЖЕНИЕ С... НЕПТУЛОНОМ... НЕОТВРАТИМО. СУМЕРЕЧНЫЙ МОЛОТ... НЕ ДОЛЖЕН ПОЛУЧИТЬ... ЭТИХ ТВАРЕЙ.',`objectives_loc8`='Уничтожьте 5 древних каналов.' WHERE `entry`=26142;
