UPDATE `locales_quest` SET `title_loc8`='Халлазил Перерожденный',`details_loc8`='<Голос Древнего врезается вам в сознание.>$B$BТЕПЕРЬ... КОГДА ТЫ $GЗАБРАЛ:ЗАБРАЛА;... ЭНЕРГИЮ... ЭТИХ ФАНАТИКОВ, ВОЙДИ... В ХРАМ... И УНИЧТОЖЬ... ХАЛЛАЗИЛА ПЕРЕРОЖДЕННОГО!',`objectives_loc8`='Уничтожьте Халлазила Перерожденного.' WHERE `entry`=26143;
