UPDATE `locales_quest` SET `title_loc8`='Пленники',`details_loc8`='Этот ключ был у одного из сектантов Сумеречного Молота. Возьми ключ и освободи узников из Альянса. Их держат в клетках в Л\'гореке.$B$BПоторопись, пока узников не принесли в жертву тому, кто таится в глубине!',`objectives_loc8`='Освободите 5 узников из Альянса.' WHERE `entry`=26144;
