UPDATE `locales_quest` SET `CompletedText_loc8`='Обратитесь к капитану Тейлору на краю Обрыва над бездной.' WHERE `entry`=26193;
UPDATE `locales_quest` SET `title_loc8`='Оборона Провала',`details_loc8`='Шепот стихий наполняет мой разум, $N...$B$BТрон Приливов подвергся осаде!$B$BНельзя сидеть сложа руки, когда наги угрожают владениям Нептулона.$B$BСобирайся! С этой тяжеловооруженной подлодкой мы не так уж и беспомощны.$B$BСкажи мне, когда будешь $Gготов:готова; к бою.',`objectives_loc8`='Обратитесь к Эрунаку Говорящему с Камнем в Зловещем гроте, чтобы вступить в битву за Обрыв над бездной.' WHERE `entry`=26194;
