UPDATE `locales_quest` SET `title_loc8`='Контроль над разумом',`details_loc8`='Внутреннего зрения мало, да.$B$BКонтроль над разумом – эта магия мощнее, да.$B$BА для сильной магии нужны сильные реагенты. Например, мозг тролля – очень сильный реагент.$B$BБрэддок в Зул\'Мамве, он очень умный, да.$B$BИди на юг, найди Брэддока и вышиби из него большой мозг.',`objectives_loc8`='Добудьте большой мозг Брэддока, убив последнего в Зул\'Мамве.' WHERE `entry`=26360;
