UPDATE `locales_quest` SET `title_loc8`='Новое унижение',`details_loc8`='Ты, наверное, $Gзаметил:заметила;, что Торговая Компания вырубила все деревья вокруг своего лагеря на востоке. Не упустят ни одной возможности получить прибыль – их штейгер превратил друидов в своих рабов и заставляет растить деревья, которые потом снова срубает.$B$BЛично я считаю, что это отвратительно.$B$BОсвободи хотя бы нескольких друидов. Они наверняка будут очень благодарны.',`objectives_loc8`='Освободите 3 порабощенных друидов в главном лагере Торговой Компании.' WHERE `entry`=26764;
