UPDATE `locales_quest` SET `title_loc8`='Мистики-властители',`details_loc8`='Мистики Каменных Игл подчинили себе грибных великанов, выросших в пропасти, там, внизу. А теперь они хотят контролировать и наших боевых созданий.$B$BОтправляйся в Шлаковый зал и сделай что-нибудь! Разве не для этого ты здесь?',`objectives_loc8`='Убейте 5 мистиков Каменных Игл.' WHERE `entry`=26770;
