UPDATE `locales_quest` SET `title_loc8`='Испытание ловушки',`details_loc8`='Теперь тебе нужно установить ловушку для матриарха.$B$BОтправляйся на западный край Алебастрового шельфа и положи мясо василиска в место кормежки.',`objectives_loc8`='Положите мясо в западной части Алебастрового шельфа.' WHERE `entry`=26771;
