UPDATE `locales_quest` SET `title_loc8`='Внутреннее зрение',`details_loc8`='Чтобы узнать Мандокира, нужно увидеть Мандокира.$B$BЧтобы увидеть Мандокира, нужны глаза ящера.$B$BМежду тобой и ящером Оган\'ака, дочерью Оган, установилась связь.$B$BЧтобы укрепить ее, нужны перья.$B$BИди на северо-восток, найдешь перья там, да.',`objectives_loc8`='Раздобудьте 5 перьев тропического ловца в Северной Тернистой долине.' WHERE `entry`=26772;
