UPDATE `locales_quest` SET `title_loc8`='Увидеть ящера',`details_loc8`='У тебя есть перья, да.$B$BУ нас есть |3-6($C), да.$B$BПоговори со жрицей, когда будешь $Gготов:готова;.',`objectives_loc8`='Поговорите со жрицей Тхаалией в форте Ливингстон, чтобы принять участие в ритуале внутреннего зрения.' WHERE `entry`=26773;
