UPDATE `locales_quest` SET `title_loc8`='Стать ящером',`details_loc8`='Контроль над разумом. Очень мощный, да.$B$BЕсли повезет, с твоей помощью Оган\'ака сбежит из Зул\'Гуруба.$B$BА потом Оган\'ака опять станет $N\'ака!$B$BПоговори со жрицей, да. И помоги $N\'ака сбежать.',`objectives_loc8`='Поговорите со жрицей Тхаалией, а затем помогите пойманному детенышу кнутохвоста сбежать из Зул\'Гуруба.' WHERE `entry`=26775;
