UPDATE `locales_quest` SET `title_loc8`='Галири',`details_loc8`='Жрица не очень хорошо всеобщий понимает, да.$B$BМожет, лучше поговорить с Галири, он вон в той палатке.$B$BРасскажи ему, что ты $Gвидел:видела; в Зул\'Гурубе, да.',`objectives_loc8`='Поговорите с Галири в форте Ливингстон в Северной Тернистой долине.' WHERE `entry`=26776;
