UPDATE `locales_quest` SET `title_loc8`='Преимущество разбойника',`details_loc8`='Уверен, что ты уже $Gосвоил:освоила; коварный удар и $Gопробовал:опробовала; его на врагах, но теперь я хочу обучить тебя технике, которая позволит осуществлять успешную серию коварных ударов. Она называется Потрошение и может послужить мощным заключительным аккордом комбинации атак.$B$BПопробуй ее применить. Найди тренировочный манекен близ юго-восточной границы Альдрассила.',`objectives_loc8`='Обучитесь Потрошению у Фрагуна Шепота Тени. Найдите тренировочный манекен к юго-востоку от Альдрассила и проведите на нем прием потрошения 3 раза.' WHERE `entry`=26946;
