UPDATE `locales_quest` SET `title_loc8`='Обучение лесного жителя',`details_loc8`='Говоря о калдорай, большинство имеет в виду друидов или часовых, но путь охотника не менее древний и почтенный.$B$BЯ наблюдала за тобой и вижу, что у тебя есть кое-какой опыт в обращении с луком. Поэтому хочу обучить тебя технике стрельбы, которую часто применяю в бою.$B$BПопытайся ее освоить. Поищи тренировочный манекен неподалеку от юго-восточной окраины Альдрассила.',`objectives_loc8`='Обучитесь верному выстрелу у Аянны Вечной Странницы. Найдите тренировочный манекен к юго-востоку от Альдрассила и произведите верный выстрел 5 раз.' WHERE `entry`=26947;
