UPDATE `locales_quest` SET `title_loc8`='Исцеление раненых',`details_loc8`='Если станешь $Gжрецом:жрицей; тебе часто придется оказывать помощь раненым товарищам. Я хочу обучить тебя базовой технике целительства, с ее помощью ты сумеешь облегчать страдания раненых и ускорять их выздоровление.$B$BОбрати приобретенные умения на исцеление раненых часовых, лечащихся в Альдрассиле.',`objectives_loc8`='Обучитесь "Быстрому исцелению" у Шанды. Используйте "Быстрое исцеление" 5 раз, чтобы вылечить искалеченных часовых в Альдрассиле.' WHERE `entry`=26949;
