UPDATE `locales_quest` SET `title_loc8`='Во тьму',`details_loc8`='Матриарх мшистых пауков находится рядом с нами! Ты можешь убить ее и тем самым положить конец паучьей угрозе!$B$BНайди матриарха в пещере Оплетающей Тьмы и уничтожь!',`objectives_loc8`='Убейте матриарха мшистых пауков.' WHERE `entry`=27094;
UPDATE `locales_quest` SET `CompletedText_loc8`='Вернитесь к полководцу Тороку в Арьергард Отрекшихся в Серебряном бору.' WHERE `entry`=27094;
UPDATE `locales_quest` SET `title_loc8`='Паучья угроза',`details_loc8`='Пришло время мстить, $N! Уже третий наш корабль затонул на северо-западе у Оплетающей Тьмы. Спасшихся на шлюпке либо похитили, либо убили местные мшистые пауки. И за это пауки должны умереть! ВСЕ ДО ОДНОГО!$B$BОтправляйся в Оплетающую Тьму и перебей всех этих насекомых!$B$BЗаодно поищи там их матку: вполне вероятно, если прикончить ее, то можно раз и навсегда избавиться от этой угрозы!',`objectives_loc8`='Убейте 12 мшистых пауков.' WHERE `entry`=27095;
