UPDATE `locales_quest` SET `title_loc8`='Свидетель',`details_loc8`='Ты отлично $Gпотрудился:потрудилась;. Отрекшиеся гордятся тобой. Чего не скажешь о нашем генерале Кольтире Ткаче Смерти.$B$BЯ собираюсь поговорить с этим рыцарем смерти. Он себя опозорил.',`objectives_loc8`='Поприсутствуйте при разговоре леди Сильваны Ветрокрылой с Кольтирой Ткачом Смерти.' WHERE `entry`=27144;
