UPDATE `locales_quest` SET `title_loc8`='Обойдетесь без оружия!',`details_loc8`='Зловещий Тотем хочет биться? Что ж, поглядим, на что они способны безоружными!$B$BНаверняка у тебя есть что-то, чтобы разжечь огонь. Предай их оружейные стойки огню, мой друг- |3-6($C).$B$BОб остальном позаботится природа.',`objectives_loc8`='Сожгите 8 оружейных стоек клана Зловещего Тотема.' WHERE `entry`=27311;
