UPDATE `locales_quest` SET `title_loc8`='Зловещий Тотем на Пике Темного Облака',`details_loc8`='Обратно дороги нет. Если хочешь выиграть битву, нужно пролить кровь. В данном случае – много крови...$B$BТы знаешь, что мы должны делать.',`objectives_loc8`='Зарубите 20 тауренов из клана Зловещего Тотема на Пике Темного Облака.' WHERE `entry`=27312;
