UPDATE `locales_quest` SET `title_loc8`='Зловещий Тотем на Пике Темного Облака',`details_loc8`='Вариантов у нас немного: если хотим выиграть сражение – нужно пролить вражескую кровь. К сожалению, немало крови.$B$BТы знаешь, что нам нужно делать.',`objectives_loc8`='Зарубите 20 тауренов из клана Зловещего Тотема на Пике Темного Облака.' WHERE `entry`=27313;
