UPDATE `locales_quest` SET `title_loc8`='Вожди Зловещего Тотема: Иша Сумрачная Секира',`details_loc8`='Азы тренировки часовых: ликвидируй предводителя врагов – и их войско вскоре разбежится. Этим и займемся, |3-6($C).$B$BИз вождей Зловещего Тотема проще всего достать Ишу Сумрачную Секиру. Примем меры по ее ликвидации.',`objectives_loc8`='Покончите с Ишей Сумрачной Секирой.' WHERE `entry`=27314;
