UPDATE `locales_quest` SET `title_loc8`='Вожди Зловещего Тотема: Иша Сумрачная Секира',`details_loc8`='Основы учения храбрецов гласят, что стоит убрать вожака врага, как в его войске скоро наступит разлад. Этим и займемся, |3-6($C).$B$BИз вождей Зловещего Тотема проще всего достать Ишу Сумрачную Секиру. Посмотрим, на что способны она и ее секира. Думаю, скоро Зловещий Тотем недосчитается одного вождя.',`objectives_loc8`='Покончите с Ишей Сумрачной Секирой.' WHERE `entry`=27315;
