UPDATE `locales_quest` SET `title_loc8`='Вожди Зловещего Тотема: старейшина Штормовое Копыто',`details_loc8`='Старейшина Штормовое Копыто – чрезвычайно могущественный шаман. Он обучался у самой Магаты Зловещий Тотем, мудрой старицы, предводительницы всего клана.$B$BИзвестно, что он здесь – тренирует заклинателей земли из клана. Мы должны прикончить его, |3-6($C).',`objectives_loc8`='Убейте старейшину Штормовое Копыто.' WHERE `entry`=27319;
