UPDATE `locales_quest` SET `title_loc8`='Старинный манускрипт',`details_loc8`='По легенде шу\'хало, костяная погремушка как-то связана со старинным манускриптом и барабанами войны. Думаю, это могущественные артефакты тауренов.$B$BНужно смотреть во все глаза, если мы хотим найти манускрипт и барабан. Если верить легенде, манускрипт выглядит просто как свиток с рисунками.',`objectives_loc8`='Отыщите старинный манускрипт.' WHERE `entry`=27320;
UPDATE `locales_quest` SET `CompletedText_loc8`='Передайте старинный манускрипт часовому Фераласа на Пике Темного Облака в Тысяче Игл.' WHERE `entry`=27320;
UPDATE `locales_quest` SET `title_loc8`='Старинный манускрипт',`details_loc8`='Костяная погремушка упоминается в древнем шу\'хальском мифе и всегда вместе со старинным манускриптом и барабанами войны. Предположительно, это могущественные артефакты тауренов – дары Матери-Земли. Правда, с трудом верится, что и с барабаном она как-то связана.$B$BМы должны удвоить бдительность, чтобы найти два оставшихся артефакта. Манускрипт должен выглядеть просто как свиток с рисунками, если мне не изменяет память.',`objectives_loc8`='Отыщите старинный манускрипт.' WHERE `entry`=27321;
UPDATE `locales_quest` SET `CompletedText_loc8`='Передайте старинный манускрипт храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.' WHERE `entry`=27321;
UPDATE `locales_quest` SET `title_loc8`='Корок Великан',`details_loc8`='Чудовище пало, и это дало небольшую передышку солдатам Отрекшихся на передовой.$B$BВозьмите вторую голову Корока и отнесите ее командиру Штурму в передовой отряд Отрекшихся.',`objectives_loc8`='Отнесите вторую голову Корока передовому командиру Штурму в передовой отряд Отрекшихся в руинах Гилнеаса.' WHERE `entry`=27322;
UPDATE `locales_quest` SET `title_loc8`='Вожди Зловещего Тотема: Грундиг Темное Облако',`details_loc8`='Вернулся один из самых мерзких предводителей Зловещего Тотема в Когтистых горах.$B$BНужно не упустить момент и сделать так, чтобы он остался здесь навечно.',`objectives_loc8`='Прикончите Грундига Темное Облако.' WHERE `entry`=27323;
