UPDATE `locales_quest` SET `title_loc8`='Барабаны войны',`details_loc8`='Для чего бы клану Зловещего Тотема ни были нужны барабаны войны, мы должны их отобрать.$B$BНе волнуйся, $N, мы сумеем разобраться, что к чему. Но сначала нужно отыскать все артефакты.',`objectives_loc8`='Разыщите барабаны войны.' WHERE `entry`=27326;
