UPDATE `locales_quest` SET `title_loc8`='Огры и эттины',`details_loc8`='Твоя задача – пробраться за эти валуны на северо-западе и попасть к Сумеречным вратам. Убей всех огров и эттинов из клана Кровавого Глаза, которых встретишь. Ну что, это тебе по плечу, а, $N?',`objectives_loc8`='Убейте 10 огров или эттинов из клана Кровавого Глаза у Сумеречных врат.' WHERE `entry`=27493;
