UPDATE `locales_quest` SET `title_loc8`='Работа для артиллеристов',`details_loc8`='Я предпочитаю сражаться честно. Эти чудовища заслужили гибель под ударами наших мечей. Однако данная ситуация требует особых мер.$B$BВозьми эту сигнальную ракету и отметь каждое из четырех зданий Сумеречных врат, находящихся к юго-западу отсюда. Об остальном позаботятся наши пушки.',`objectives_loc8`='С помощью артиллерийской сигнальной ракеты отметьте северное, северо-восточное, юго-западное и южное здание Сумеречных врат.' WHERE `entry`=27496;
