UPDATE `locales_quest` SET `title_loc8`='Сигнал к атаке',`details_loc8`='Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!',`objectives_loc8`='Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.' WHERE `entry`=27498;
