UPDATE `locales_quest` SET `title_loc8`='Послание баронессы',`details_loc8`='Это записка от баронессы Анастари, в ней описан ритуал, который должен пройти в бойне – в самом центре Чумного леса, к югу от того места, где находится Таренар. Возможно, именно там они держат Гидвина!$B$BНужно сообщить об этом Таренару... и как можно быстрее!',`objectives_loc8`='Отнесите послание баронессы Таренару.' WHERE `entry`=27551;
