UPDATE `locales_quest` SET `title_loc8`='За закрытыми дверьми',`details_loc8`='Галганн Огнемолот и его банда дворфов из клана Черного Железа заняли третий раскоп и охраняют какую-то дверь, о которой мы ничего не знаем! Они мешают нам работать. Причем их здесь вообще быть не должно. Только у Лиги исследователей есть официальное разрешение на изучение артефактов на территории Ульдамана!$B$BИди на третий раскоп и разгони эту шайку, чтобы мы могли спокойно работать. Я хочу знать, что скрывается за той дверью!',`objectives_loc8`='Убейте Галганна Огнемолота.' WHERE `entry`=27676;
