UPDATE `locales_quest` SET `title_loc8`='Скреж, да не наш',`details_loc8`='Вот это подвиг – одолеть могучего морского гиганта!$B$BНовые обитатели Пещере контрабандистов будут чувствовать себя гораздо спокойнее, зная, что это чудище не шатается где-то поблизости.',`objectives_loc8`='Принесите голову Скрежа Самиру в Пещеру контрабандистов.' WHERE `entry`=27687;
UPDATE `locales_quest` SET `title_loc8`='Отвлекающий маневр',`details_loc8`='Необходимо уничтожить троих: госпожу Элис Финнссон, мастера Клема и Мию Цветущую.$B$BМне нужно, чтобы ты их $Gотвлек:отвлекла;. А я выберу подходящий момент, подберусь к ним со спины и прикончу.$B$BТолько будь $Gосторожен:осторожна;, $N. Не стоит их недооценивать. Они опасные соперники, сильные и безжалостные.',`objectives_loc8`='Убейте госпожу Элис Финнссон, мастера Клема и Мию Цветущую.' WHERE `entry`=27688;
