UPDATE `locales_quest` SET `title_loc8`='Отвлекающий маневр',`details_loc8`='Необходимо уничтожить троих: госпожу Элис Финнссон, мастера Клема и Мию Цветущую.$B$BМне нужно, чтобы ты их $Gотвлек:отвлекла;. А я выберу подходящий момент, подберусь к ним со спины и прикончу.$B$BТолько, прошу тебя, будь $Gосторожен:осторожна;, $N. Не стоит их недооценивать. Они опасные соперники, сильные и безжалостные. И при этом – форменные психопаты.',`objectives_loc8`='Убейте госпожу Элис Финнссон, мастера Клема и Мию Цветущую.' WHERE `entry`=27689;
