UPDATE `locales_quest` SET `title_loc8`='Освобождение дракона',`details_loc8`='Лирастраза – последняя и величайшая из красных драконов, которых захватил Сумеречный Молот. Они собираются убить ее, |3-6($C).$B$BВозьми топор из элементия и освободи ее от оков.',`objectives_loc8`='Топором из элементия разрубите цепи, которыми скована Лирастраза.' WHERE `entry`=27701;
