UPDATE `locales_quest` SET `title_loc8`='Удар милосердия',`details_loc8`='Смотри! Лирастраза сражается с ними!$B$BМы должны добить тех драконов, которых она сбила, но не прикончила, $N. Мы же не хотим, чтобы целители Сумеречного Молота вновь подняли их в воздух.$B$BНазовем это проявлением милосердия к проигравшим.',`objectives_loc8`='Добейте 5 сумеречных ужасов небес.' WHERE `entry`=27702;
