UPDATE `locales_quest` SET `title_loc8`='Удар милосердия',`details_loc8`='Ты гляди, что творится! Лирастраза сражается с ними!$B$BНекоторых драконов она сбила, но не прикончила. Мы должны завершить начатое ею, $N. Мы же не хотим, чтобы поганые целители Сумеречного Молота вновь подняли их в воздух.$B$BНазовем это проявлением милосердия к проигравшим.',`objectives_loc8`='Добейте 5 сумеречных ужасов небес.' WHERE `entry`=27703;
