UPDATE `locales_quest` SET `title_loc8`='Прокатимся с ветерком',`details_loc8`='Значит, так, $N. Нам надо добраться до портала земли в самом дальнем конце пещеры.$B$BЯ сделал умно – "раздобыл" транспорт. Зачем трудить ноги, когда можно проехаться с ветерком? Надеюсь, твоя религия не запрещает кататься на шахтерских тачках?$B$BВ общем, как будешь $Gготов:готова;, скажи – и поедем.',`objectives_loc8`='Вместе с посвященным Клондацком прокатитесь на вагонетке до конца маршрута.' WHERE `entry`=27720;
