UPDATE `locales_quest` SET `title_loc8`='На нас напали!',`details_loc8`='Войска Альянса у наших стен!$B$BТвои действия их задержали и ослабили, $N, но все-таки мы в меньшинстве. Это наш последний бой. Победа – или смерть...$B$BСражайся с честью, $N. В данную минуту враг уже проник в город. Выдворим человечишек из Каменора! За Орду!',`objectives_loc8`='Убейте 12 захватчиков Болотных Волн.' WHERE `entry`=27857;
