UPDATE `locales_quest` SET `title_loc8`='Сокровище титанов',`details_loc8`='Второй защитник падает замертво, и у задней стены зала появляется сундук. Быть может, это как раз то, что они охраняли?',`objectives_loc8`='Осмотрите сокровище стражей.' WHERE `entry`=27912;
