UPDATE `locales_quest` SET `title_loc8`='Освободите Сердцереза',`details_loc8`='Культ Сумеречного Молота захватил главного самца Скального гнездовья. Иди на восток вверх по горе и освободи Сердцереза, пока прайд не потерял своего вожака!',`objectives_loc8`='Освободите Сердцереза от всех сдерживающих его пут.' WHERE `entry`=28088;
