UPDATE `locales_quest` SET `title_loc8`='Врата Грим Батола',`details_loc8`='Крогг уже пошел в атаку. Он к юго-востоку отсюда, сразу за вратами.$B$BЯ соберу отряд и поведу его в наступление. Увидимся там.',`objectives_loc8`='Отправляйтесь в Излучину Змея и поговорите с полководцем Кроггом.' WHERE `entry`=28097;
UPDATE `locales_quest` SET `title_loc8`='Распорядитель полетов Сумеречного Молота',`details_loc8`='Наверху на юго-востоке, в Сумеречном гнездилище, расположился сумеречный повелитель небес Рихтофен. Если мы с ним не разделаемся – все наши усилия здесь внизу напрасны, надежды для Скального гнездовья нет.$B$BХоть Сердцерез пока еще слишком слаб, чтобы помочь тебе в бою, он сможет отнести тебя на вершину. Остальное я вверяю тебе, $N.$B$BУдачи.',`objectives_loc8`='Летите на Сердцерезе в Сумеречное гнездилище и покончите с сумеречным повелителем небес Рихтофеном.' WHERE `entry`=28098;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Летите на Сердцерезе',`ObjectiveText2_loc8`='Вы разделались с сумеречным повелителем небес Рихтофеном' WHERE `entry`=28098;
