UPDATE `locales_quest` SET `title_loc8`='Кавем Бессердечный',`details_loc8`='Кавем отличался жестокостью еще до объединения неферсетов со Смертокрылом – теперь же его садизм граничит с безумием.$B$BЭто он хранит ключи от наших оков.$B$BНайти его можно в соседнем здании, справа.$B$BРазыщи его и забери у него ключ. Не колеблись и не проявляй сострадания – он при первом удобном случае перерезал бы тебе горло без каких-либо раздумий.',`objectives_loc8`='Заберите неферсетский ключ у Кавема Бессердечного.' WHERE `entry`=28105;
