UPDATE `locales_quest` SET `title_loc8`='Встреча со жрицей Лореной',`details_loc8`='Я только что получил свиток из Собора Света, $N. Верховная жрица Лорена пишет, что хочет поговорить с тобой. Тебе нужно встретиться с ней как можно скорее.',`objectives_loc8`='Поговорите с верховной жрицей Лореной в Соборе Света, что в Соборном квартале Штормграда.' WHERE `entry`=28285;
