UPDATE `locales_quest` SET `title_loc8`='На сегодня хватит крови',`details_loc8`='Торг\'изог со своим кланом Черной горы больше не является для нас стратегически важной целью. Давай перейдем к следующей фазе операции.$B$BКогда закончишь свои дела в крепости, возвращайся в Узкоклинье.',`objectives_loc8`='Явитесь к полковнику Тротману в Узкоклинье.' WHERE `entry`=28286;
