UPDATE `locales_quest` SET `title_loc8`='Встреча с прорицательницей Умбруа',`details_loc8`='Ко мне только что прибыл гонец от прорицательницы Умбруа, $N. У нее есть какое-то важное дело, которое она бы хотела обсудить с тобой, и она просит тебя как можно скорее встретиться с ней в таверне "Золотой бочонок" в Квартале Дворфов Штормграда.',`objectives_loc8`='Поговорите с прорицательницей Умбруа в таверне "Золотой бочонок" в Квартале Дворфов Штормграда.' WHERE `entry`=28287;
