UPDATE `locales_quest` SET `title_loc8`='Лунная поляна зовет',`details_loc8`='Я только что узнала, что одному из наших братьев на Лунной поляне нужна твоя помощь, $N. Отправляйся туда и поговори с Логанааром. Его можно найти в Ночной Гавани. Он расскажет тебе все, что нужно.',`objectives_loc8`='Отправляйтесь в Лунную поляну и поговорите с Логанааром в Ночной Гавани.' WHERE `entry`=28289;
