UPDATE `locales_quest` SET `title_loc8`='Встреча с Греззом Десницей Гнева',`details_loc8`='Грезз Десница Гнева прислал для тебя срочное сообщение, $N. Он хочет, чтобы ты немедленно $Gприбыл:прибыла; к нему в Оргриммар, на Аллею Героев. Должно быть, у него есть для тебя важное задание.',`objectives_loc8`='Поговорите с Греззом Десницей Гнева на Аллее Чести в Оргриммаре.' WHERE `entry`=28290;
