UPDATE `locales_quest` SET `title_loc8`='Встреча с Зевростом',`details_loc8`='Я только что получил сообщение от Зевроста, главного наставника чернокнижников Оргриммара. Он хочет, чтобы как можно быстрее $Gприбыл:прибыла; в Оргриммар и $Gпоговорил:поговорила; с ним в Расселине Теней. Должно быть, у него есть для тебя важное задание.',`objectives_loc8`='Поговорите с Зевростом в Расселине Теней в Оргриммаре.' WHERE `entry`=28299;
