UPDATE `locales_quest` SET `title_loc8`='Встреча с Уредой',`details_loc8`='Я только что получил свиток из Оргриммара, $N. Он от Уреды, она – одна из тамошних наставниц магов. Она хочет, чтобы ты $Gвстретился:встретилась; с ней в Расселине Теней, когда в следующий раз будешь в городе.',`objectives_loc8`='Поговорите с Уредой в Расселине Теней в Оргриммаре.' WHERE `entry`=28300;
