UPDATE `locales_quest` SET `title_loc8`='Встреча с Кардрисом Сновидицей',`details_loc8`='Я только получила срочное сообщение, адресованное тебе, $N. Оно от Кардрис Сновидицы, одной из наставниц шаманов Оргриммара. Она просит тебя как можно скорее поговорить с ней. Кардрис можно найти в Оргриммаре на Аллее Мудрости.',`objectives_loc8`='Поговорите с Кардрис Сновидицей на Аллее Мудрости в Оргриммаре.' WHERE `entry`=28301;
