UPDATE `locales_quest` SET `title_loc8`='Встреча со служителем солнца Атомо',`details_loc8`='Мне нужно как можно скорее отправить тебя в Оргриммар, $N. Служитель солнца Атомо сообщил, что он хочет поговорить с тобой о деле, имеющем огромную важность для Орды. Ищи его на Аллее Мудрости.',`objectives_loc8`='Поговорите со служителем солнца Атомо на Аллее Мудрости Оргриммара.' WHERE `entry`=28302;
