UPDATE `locales_quest` SET `title_loc8`='Встреча с наставником Огненором',`details_loc8`='Наставник Огненор прислал для тебя срочное сообщение, $N. Он просит тебя прибыть к нему в крепость Громмаш, которая находится на Аллее Силы Оргриммара, когда ты следующий раз будешь в городе. У него есть для тебя важное задание.',`objectives_loc8`='Поговорите с наставником Огненором в крепости Громмаш в Оргриммаре.' WHERE `entry`=28303;
