UPDATE `locales_quest` SET `title_loc8`='Надувные пони спешат на помощь',`details_loc8`='Из-за этого кретина – вон напротив стоит – наши гибнут!$B$BЭтот Бретт "Криворучко" развернул Психходельню черт знает где, теперь тут все на честном слове держится... Взрывами, вызванными неустойчивостью, наших рабочих сметает с платформ прямо в воду.$B$B$N, может быть, слетаешь вниз и сбросишь им на подмогу надувных пони?',`objectives_loc8`='Сбросьте надувных пони 10 работникам Психходельни, свалившимся в воду.' WHERE `entry`=28586;
