UPDATE `locales_quest` SET `title_loc8`='Слезная река, Высокие берега',`details_loc8`='Поди и сделай отбивную из этих отбросов Альянса! Из кого хочешь – на твой вкус. Хочу, чтобы ты там $Gустроил:устроила; переполох, пока будешь выполнять основное задание.$B$BКак закончишь, возвращайся к нам, к восточной башне.',`objectives_loc8`='Убейте 10 защитников Высокого берега.' WHERE `entry`=28594;
