UPDATE `locales_quest` SET `title_loc8`='Вызов Дарнхольда: Кровояд',`details_loc8`='В соответствии с руководством твоим следующим противником будет Кровояд. Найти этого ужасного элементаля можно на нижнем этаже крепости Дарнхольд, возле западных темниц.',`objectives_loc8`='Убейте Кровояда.' WHERE `entry`=28645;
