UPDATE `locales_quest` SET `title_loc8`='Вызов Дарнхольда: Инферний',`details_loc8`='В соответствии с руководством твоим следующим противником будет Инферний. Этого монстра, состоящего из кипящей лавы и бушующего огня, можно найти на нижнем этаже крепости Дарнхольд, возле восточных темниц.',`objectives_loc8`='Убейте Инферния.' WHERE `entry`=28646;
