UPDATE `locales_quest` SET `title_loc8`='Вызов Дарнхольда: Д-1000',`details_loc8`='На арене старой крепости Дарнхольд тебя ждет существо, целиком состоящее из чистой ртути. Отрекшиеся дали ему имя Д-1000. Убей Д-1000, и приз твой!',`objectives_loc8`='Убейте Д-1000.' WHERE `entry`=28647;
