UPDATE `locales_quest` SET `title_loc8`='Новобранец Элрет',`details_loc8`='Теперь, когда тренировка закончена, почему бы тебе не поговорить с Элрет? Она служит жрецу Тени Сарвису и, наверное, у нее найдутся задания, в которых ты $Gмог:могла; бы применить свои новые способности.',`objectives_loc8`='Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.' WHERE `entry`=28651;
