UPDATE `locales_quest` SET `title_loc8`='Разбитая статуэтка змеи',`details_loc8`='Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.',`objectives_loc8`='Почините разбитую статуэтку, применив необходимые умения и материалы.' WHERE `entry`=28775;
UPDATE `locales_quest` SET `title_loc8`='Разбитая статуэтка земельника',`details_loc8`='Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.',`objectives_loc8`='Почините разбитую статуэтку, применив необходимые умения и материалы.' WHERE `entry`=28776;
