UPDATE `locales_quest` SET `title_loc8`='Персональное приглашение',`details_loc8`='<В вас нарастает незнакомое чувство, наполняя весь ваш разум невиданными образами и странными мыслями.>$B$BУслышь меня, $N.$B$BНаш мир на грани жуткой катастрофы.$B$BВзываю к тебе: окажи нам помощь в этот трудный час.$B$BЯ Крогар.$B$BНайди меня, и я открою тебе твое предназначение.$B$BЖду тебя в Оргриммаре, к северу от Волока.',`objectives_loc8`='Предсказатель Крогар просит вас встретиться с ним в Оргриммаре.' WHERE `entry`=28790;
UPDATE `locales_quest` SET `title_loc8`='Враг подослал наемных убийц',`details_loc8`='Ты когда-нибудь $Gвстречал:встречала; гоблина, $N? Это презренные зеленокожие монстры, любящие лишь две вещи: золото и самих себя.$B$BОрки Черной горы прибегли к услугам гоблинов, промышляющих наемными убийствами, чтобы те убивали наших солдат. Погляди на поле к северу от нас: ты вряд ли разглядишь, как они маскируются в траве.$B$BХочу, чтобы ты $Gпошел:пошла; туда и $Gперебил:перебила; всех гоблинов, которых сможешь найти. Пусть узнают, что не следует выступать против Альянса.',`objectives_loc8`='Прикончите 8 гоблинов-убийц.' WHERE `entry`=28791;
