UPDATE `locales_quest` SET `title_loc8`='Пастыри и паства',`details_loc8`='В бумагах описывается визит верховной жрицы Азил в глубины Каменных Недр.$B$BИсходя из изложенного, Азил – высокопоставленный член Сумеречного Совета, а ее кортеж более чем из ста верных последователей готовится провести темный ритуал необыкновенно разрушительной силы.$B$BПохоже, вам стоит воспрепятствовать осуществлению их планов.',`objectives_loc8`='Убейте верховную жрицу Азил и 101 верного последователя.' WHERE `entry`=28814;
