UPDATE `locales_quest` SET `title_loc8`='Спасение Эрунака',`details_loc8`='Отлично! Ты $Gпришел:пришла; не одна.$B$BЕсли мы хотим спасти Эрунака, надо поторопиться.$B$BПробейся сквозь залы Нептулона. Найди шамана и освободи его от этих червей... если он еще жив.$B$BЯ прикрою тебя с тыла. Мимо меня ни одна тварь не проскочит!',`objectives_loc8`='Освободите Эрунака Говорящего с Камнем.' WHERE `entry`=28834;
