UPDATE `locales_quest` SET `title_loc8`='Хлебные крошки Альянса',`details_loc8`='Чудовища! Просто чудовища!$B$BНаш корабль зашел в порт к югу от Cтромгарда, но на берегу нас ждала стая странных созданий.$B$BПеред тем как смыться оттуда, я успел обратить внимание на их противные морды и странные булькающие звуки, которые они издавали. Лучше поспеши на помощь моим товарищам, $N!',`objectives_loc8`='Поговорите с Леди Гаргой в бухте Фальдира.' WHERE `entry`=28937;
