UPDATE `locales_quest` SET `title_loc8`='Сломить их дух',`details_loc8`='Зул\'Гуруб похож на те высокие деревья, которые растут поблизости.$B$BКаким бы мощным ни был ствол и какой бы густой – крона, без простирающихся далеко под землей корней дерево засохнет и рухнет.$B$BСила армии Джин\'до во многом зависит от помощи двух троллей Гурубаши. Стоит перерубить эти "корни", и город падет.',`objectives_loc8`='Убейте Габа и шеф-повара племени Гурубаши в Зул\'Гурубе в героическом режиме.' WHERE `entry`=29175;
