UPDATE `locales_quest` SET `title_loc8`='Маути',`details_loc8`='У меня есть ощущение, что с этой пантерой что-то не так, $N. Все это кажется противоестественным. Мне нужно провести некоторые ритуалы. Убей Маути, $N, и после этого мы посмотрим, что удастся выяснить.',`objectives_loc8`='Приведите Бвембу к останкам Маути.' WHERE `entry`=29230;
