UPDATE `locales_quest` SET `title_loc8`='Украсть магмолии',`details_loc8`='Мы обнаружили новый вид цветов в Магматических ключах, что к северу отсюда. Это совершенно удивительно – они растут прямо в кипящей лаве!$B$BПожалуйста, сходи туда и собери для меня несколько образцов. Уверена, их детальное изучение поможет разгадать загадку твоего маленького друга.$B$BКстати, о нем – похоже, он очень хочет пойти с тобой. Будем надеяться, он сумеет вести себя прилично.',`objectives_loc8`='Соберите 8 магмолий в Магматических ключах к северу.' WHERE `entry`=29257;
