UPDATE `locales_quest` SET `title_loc8`='Прятки',`details_loc8`='Приятно вновь видеть тебя, $N. Твой плеточник придумал новую игру – прятки!$B$BИ, кажется, ему хочется поиграть с тобой.$B$BДождись, когда он спрячется, а потом ищи его здесь в лагере.$B$BА на случай, если найти его будет слишком сложно, – вот эта специальная дымка укажет направление, в котором нужно искать. Но не говори ему, что это я тебе помогла.',`objectives_loc8`='Найдите спрятавшегося огненного плеточника на Аванпосте Малфуриона.' WHERE `entry`=29259;
