UPDATE `locales_quest` SET `title_loc8`='Посох легенд',`details_loc8`='Это честь – познакомиться с тобой, |3-6($R).$B$BВсе существа Азерота, смертные и бессмертные, знают о твоих деяниях.$B$BКогда Калесгос появится здесь, я передам ему сердце Рагнароса. Пусть его сила укрепит твое оружие.$B$BЦеремония скоро начнется. Меня попросили сопровождать тебя, когда ты будешь $Gготов:готова;.',`objectives_loc8`='Поговорите с Халлегосой.' WHERE `entry`=29309;
