UPDATE `locales_quest` SET `title_loc8`='Время созидать',`details_loc8`='Мы сжигаем Плетеного человека, как знак нашей борьбы с теми, кто выступает против нас. Мы раскрашиваем лица пеплом, что символизирует нашу нескончаемую борьбу с теми, кто хочет поработить нас.$B$BВоспользуйся костром и подожги Плетеного человека. Потом возьми пепел и раскрась им лицо.$B$BПусть все это напомнит нашим врагам о том, что мы никогда не сдадимся.',`objectives_loc8`='Воспользуйтесь большим костром, чтобы поджечь Плетеного человека. Потом воспользуйтесь пеплом, который появится на земле возле Плетеного человека.' WHERE `entry`=29376;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Воспользуйтесь костром.',`ObjectiveText2_loc8`='Воспользуйтесь пеплом Плетеного человека' WHERE `entry`=29376;
