UPDATE `locales_quest` SET `title_loc8`='Спасибо, конечно, но…',`details_loc8`='Не каждому достается праздничный свитер.$B$BВ квитанции сказано, что вы можете обменять его на золото у любого торговца пастбищ Дымного леса.$B$BОтменить сделку будет нельзя.',`objectives_loc8`='Если вам правда не нравится ваш подарок, вы можете обменять его на золото, поговорив с одним из торговцев пастбищ Дымного леса.$B$BОтменить сделку будет нельзя.' WHERE `entry`=29382;
