UPDATE `locales_quest` SET `title_loc8`='Загадочный гримуар',`details_loc8`='Трудно сказать, кому принадлежала эта массивная книга. Ее страницы испещрены разнообразными заклинаниями и описаниями чар, лишь немногие из которых вам кажутся знакомыми.$B$BВ "Энциклопедии искателя приключений" ярмарки Новолуния сказано, что подобные книги могут представлять интерес для Воржея, ярмарочного предсказателя.',`objectives_loc8`='Отнесите загадочный гримуар Воржею на ярмарку Новолуния, проходящую на Острове Новолуния.' WHERE `entry`=29445;
