UPDATE `locales_quest` SET `title_loc8`='Захваченный дневник',`details_loc8`='Потрепанная кожаная обложка этой тетради заляпана грязью и залита кровью. Перелистывая страницы, вы понимаете, что в руках у вас личный дневник некого искателя приключений из Альянса. Автор явно был высокого мнения о собственной персоне и о своих деяниях.$B$BПрофессор Таддеус Палео с ярмарки Новолуния наверняка не отказался бы заглянуть в этот дневник.',`objectives_loc8`='Отнесите дневник профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.' WHERE `entry`=29458;
