UPDATE `locales_quest` SET `title_loc8`='Кстати, о танках',`details_loc8`='Паровые танки – одно из самых популярных развлечений на ярмарке Новолуния. Посетители ярмарки могут часами участвовать в танковых сражениях, но нередко танки от этого ломаются.$B$BТы, похоже, знаешь, как пользоваться отверткой. Так может быть ты починишь несколько танков? Я заплачу тебе за работу.',`objectives_loc8`='Почините 5 сломанных паровых танков на территории ярмарки Новолуния.' WHERE `entry`=29511;
