UPDATE `locales_quest` SET `title_loc8`='Поставить работников на ноги',`details_loc8`='Работать на ярмарке Новолуния небезопасно, $N. Не секрет, что многие из наших работников получают травмы при установке, разборке или транспортировке всех этих аттракционов.$B$BНекоторые из пострадавших находятся прямо здесь, у фургонов. Остальные – в лечебном шатре неподалеку, там им оказывают первую помощь. Сможешь помочь раненым работникам при помощи этих бинтов?',`objectives_loc8`='Воспользуйтесь бинтами ярмарки Новолуния, чтобы вылечить 4 раненых работников.' WHERE `entry`=29512;
UPDATE `locales_quest` SET `ObjectiveText1_loc8`='Перебинтовать раненых работников' WHERE `entry`=29512;
