UPDATE `locales_quest` SET `title_loc8`='Боец арены',`details_loc8`='Должно быть, стать хорошим бойцом арены не так просто...$B$BБыть может, Коргол Череподроб, который организует схватки Новолуния, знает, в чем тут штука!',`objectives_loc8`='Поговорите с Корголом Череподробом на арене ярмарки Новолуния.' WHERE `entry`=29760;
